      <input type="text" [(ngModel)]="todo.task">
      <button (click)="deleteTodo(todo.task)">Delete Task</button>
    </li>
  </ul>
</div>

<script>
  import { Component } from '@angular/core';

  @Component({
    selector:'my-app',
    template: `
      <h1>Todo App</h1>
      <todo-list [todos]="todos"></todo-list>
    `
  })
  export class AppComponent {
    todos = [
      { task: 'Learn Angular' },
      { task: 'Go for a run' },
      { task: 'Buy a coffee' },
    ];
    addTodo(text: string) {
      this.todos.push({ task: text });
    }
    deleteTodo(task: string) {
      this.todos = this.todos.filter(todo => todo.task!== task);
    }
  }
</script>
```

This component creates a list of todo items using an array of todos. It has a button that adds a new todo item, a delete button that deletes a todo item, and an input field for the task. The component also includes a todo-list component that displays the todos in a list.

