```javascript
class SimpleLinearRegression {
  constructor(lr = 0.01, epochs = 100) {
    this.lr = lr;
    this.epochs = epochs;
    this.m = 0;
    this.b = 0;
  }

  train(x, y) {
    for (let epoch = 0; epoch < this.epochs; epoch++) {
      let dm = 0;
      let db = 0;
      const n = x.length;

      for (let i = 0; i < n; i++) {
        const pred = this.m * x[i] + this.b;
        const error = y[i] - pred;
        dm += -2 * x[i] * error;
        db += -2 * error;
      }

      this.m -= this.lr * (dm / n);
      this.b -= this.lr * (db / n);
    }
  }

  predict(x) {
    return x.map(val => this.m * val + this.b);
  }
}

// Example usage
