Here's an example of how to implement theECDSA signature algorithm in TypeScript:
```typescript
function ECDSA(privateKey: string, publicKey: string): string {
  const signature: string =  signatureAlgorithm(privateKey, publicKey);
  return signature.toString();
}

function signatureAlgorithm(privateKey: string, publicKey: string): string {
  const ECDSAECDSA = '0123456789abcdef';
  const privateKeyWithout Sign = privateKey.replace(/[.-]/g, '').split('').reduce((sum, char) => sum + char, 0);
  const publicKeyWithout Sign = publicKey.replace(/[.-]/g, '').split('').reduce((sum, char) => sum + char, 0);

  const privateToPublic = (privateKey: string): string => {
    return publicKey.replace(/^private\s*=\s*[.-]/g, (match) => `$1: ${privateKey}$2`.replace(/\s+/g, '').replace(/\s*$/g, '').replace(/\s*,\s*$/g, '').split(':');
  };

  const publicToPrivate = (publicKey: string): string => {
    return privateKeyWithout Sign.replace(/(.-) private\s*=\s*(\d{4}) (\d{4})/g, (match) => `$1: ${match[0]}: ${match[1]}: ${match[2]}`).replace(/\s+/g, '').replace(/\s*$/g, '').replace(/\s*,\s*$/g, '').split(':');
  };

  return privateToPublic(privateKey) +'' + publicToPrivate(publicKey);
}
```
This function first converts the private key and public key into their respective string representations. Then, it uses the `ECDSA` function to compute the signature using the private key and the public key. Finally, it returns the signature as a string.

